<template>
  <main aria-labelledby="project-detail-title">
    <div class="d-flex align-center flex-wrap ga-2 mb-4">
      <v-btn variant="text" prepend-icon="mdi-arrow-left" :to="{ name: 'Projects' }">Dự án</v-btn>
      <span class="text-medium-emphasis" aria-hidden="true">/</span>
      <span class="text-body-2 text-medium-emphasis">{{ project?.projectCode ?? 'Đang tải' }}</span>
    </div>
    <v-alert v-if="error" type="error" class="mb-4"><div class="d-flex align-center"><span>{{ error }}</span><v-spacer /><v-btn variant="text" @click="load">Thử lại</v-btn></div></v-alert>
    <v-progress-linear v-if="loading" indeterminate color="primary" class="mb-4" />
    <template v-if="project">
      <header class="d-flex align-start flex-wrap ga-3 mb-5">
        <div><h1 id="project-detail-title" class="text-h5">{{ project.name }}</h1><p v-if="project.description" class="text-body-2 text-medium-emphasis mt-1">{{ project.description }}</p></div>
        <v-spacer /><v-chip :color="statusColor(project.status)" variant="tonal">{{ statusLabel(project.status) }}</v-chip>
        <v-btn color="primary" prepend-icon="mdi-pencil" min-height="40" @click="openProjectEdit">Chỉnh sửa</v-btn>
      </header>

      <v-row class="mb-2"><v-col cols="6" sm="3"><v-card variant="outlined"><v-card-text><div class="text-caption text-medium-emphasis">Tiến độ</div><div class="text-h6">{{ project.progress }}%</div><v-progress-linear :model-value="project.progress" rounded height="6" class="mt-2" /></v-card-text></v-card></v-col><v-col cols="6" sm="3"><v-card variant="outlined"><v-card-text><div class="text-caption text-medium-emphasis">Hạn hoàn thành</div><div :class="{ 'text-error font-weight-medium': isOverdue(project.dueAt, project.status) }">{{ localDate(project.dueAt) }}</div></v-card-text></v-card></v-col><v-col cols="6" sm="3"><v-card variant="outlined"><v-card-text><div class="text-caption text-medium-emphasis">Công việc</div><div class="text-h6">{{ tasks.length }}</div></v-card-text></v-card></v-col><v-col cols="6" sm="3"><v-card variant="outlined"><v-card-text><div class="text-caption text-medium-emphasis">Thành viên</div><div class="text-h6">{{ members.length }}</div></v-card-text></v-card></v-col></v-row>

      <v-tabs v-model="tab" color="primary" grow class="mb-4" aria-label="Nội dung dự án"><v-tab value="overview">Tổng quan</v-tab><v-tab value="tasks">Công việc</v-tab><v-tab value="milestones">Mốc</v-tab><v-tab value="members">Thành viên</v-tab><v-tab value="activity">Hoạt động</v-tab></v-tabs>
      <v-window v-model="tab">
        <v-window-item value="overview"><v-row><v-col cols="12" md="7"><v-card variant="outlined"><v-card-title>Tóm tắt dự án</v-card-title><v-card-text><dl class="summary-grid"><dt>Mức ưu tiên</dt><dd><v-chip size="small" :color="priorityColor(project.priority)" variant="tonal">{{ priorityLabel(project.priority) }}</v-chip></dd><dt>Ngày bắt đầu</dt><dd>{{ localDate(project.startAt) }}</dd><dt>Chủ dự án</dt><dd>{{ project.owner?.fullName ?? '—' }}</dd><dt>Ngân sách</dt><dd>{{ project.budget == null ? '—' : money(project.budget) }}</dd></dl></v-card-text></v-card></v-col><v-col cols="12" md="5"><v-card variant="outlined"><v-card-title>Khách hàng liên kết</v-card-title><v-card-text v-if="project.clientContact"><div class="font-weight-medium">{{ project.clientContact.fullName ?? 'Khách hàng chưa có tên' }}</div><div class="text-body-2 text-medium-emphasis">{{ project.clientContact.phone ?? project.clientContact.email ?? 'Chưa có thông tin liên hệ' }}</div><v-btn :to="{ name: 'Contacts' }" variant="text" class="mt-2" append-icon="mdi-arrow-right">Mở danh sách khách hàng</v-btn></v-card-text><v-card-text v-else class="text-medium-emphasis">Chưa liên kết khách hàng CRM.</v-card-text></v-card></v-col></v-row></v-window-item>
        <v-window-item value="tasks"><section aria-labelledby="tasks-heading"><div class="d-flex align-center mb-3"><h2 id="tasks-heading" class="text-h6">Công việc</h2><v-spacer /><v-btn color="primary" prepend-icon="mdi-plus" min-height="40" @click="openTask">Thêm công việc</v-btn></div><div class="task-board" aria-label="Bảng công việc Kanban"><section v-for="column in taskStatuses" :key="column.value" class="task-column"><div class="d-flex align-center mb-2"><h3 class="text-subtitle-2">{{ column.title }}</h3><v-spacer /><v-chip size="x-small">{{ tasksByStatus[column.value]?.length ?? 0 }}</v-chip></div><v-card v-for="task in tasksByStatus[column.value]" :key="task.id" variant="outlined" class="mb-2"><v-card-text><div class="font-weight-medium">{{ task.title }}</div><div class="d-flex align-center mt-2"><v-chip size="x-small" :color="priorityColor(task.priority)" variant="tonal">{{ priorityLabel(task.priority) }}</v-chip><v-spacer /><span :class="['text-caption', { 'text-error': isOverdue(task.dueAt, task.status) }]">{{ localDate(task.dueAt) }}</span></div><div class="text-caption text-medium-emphasis mt-2">{{ task.assignee?.fullName ?? 'Chưa giao' }}</div><v-select :model-value="task.status" :items="taskStatuses" item-title="title" item-value="value" label="Chuyển trạng thái" density="compact" variant="outlined" hide-details class="mt-3" :aria-label="`Trạng thái công việc ${task.title}`" @update:model-value="moveTask(task, $event)" /></v-card-text></v-card><p v-if="!tasksByStatus[column.value]?.length" class="text-caption text-medium-emphasis pa-2">Chưa có công việc.</p></section></div></section></v-window-item>
        <v-window-item value="milestones"><section aria-labelledby="milestones-heading"><div class="d-flex align-center mb-3"><h2 id="milestones-heading" class="text-h6">Mốc công việc</h2><v-spacer /><v-btn color="primary" prepend-icon="mdi-plus" min-height="40" @click="openMilestone">Thêm mốc</v-btn></div><v-card variant="outlined"><v-list lines="two"><template v-for="(milestone, index) in milestones" :key="milestone.id"><v-list-item><template #prepend><v-icon :color="statusColor(milestone.status)">mdi-flag-checkered</v-icon></template><v-list-item-title>{{ milestone.title }}</v-list-item-title><v-list-item-subtitle :class="{ 'text-error': isOverdue(milestone.dueAt, milestone.status) }">Hạn: {{ localDate(milestone.dueAt) }} · {{ milestone.description || 'Không có mô tả' }}</v-list-item-subtitle><template #append><v-select :model-value="milestone.status" :items="milestoneStatuses" density="compact" variant="outlined" hide-details class="milestone-status" aria-label="Cập nhật trạng thái mốc" @update:model-value="changeMilestone(milestone, $event)" /></template></v-list-item><v-divider v-if="index < milestones.length - 1" /></template><v-list-item v-if="!milestones.length" title="Chưa có mốc công việc" subtitle="Thêm mốc để theo dõi các kết quả quan trọng." /></v-list></v-card></section></v-window-item>
        <v-window-item value="members"><section aria-labelledby="members-heading"><div class="d-flex align-center mb-3"><h2 id="members-heading" class="text-h6">Thành viên</h2><v-spacer /><v-btn color="primary" prepend-icon="mdi-account-plus-outline" min-height="40" @click="openMember">Thêm thành viên</v-btn></div><v-card variant="outlined"><v-list><template v-for="(member, index) in members" :key="member.id"><v-list-item><template #prepend><v-avatar color="primary" variant="tonal">{{ member.user.fullName.slice(0, 1).toUpperCase() }}</v-avatar></template><v-list-item-title>{{ member.user.fullName }}</v-list-item-title><v-list-item-subtitle>{{ member.user.email ?? '—' }}</v-list-item-subtitle><template #append><v-chip size="small" variant="tonal">{{ accessLabel(member.access) }}</v-chip><v-btn v-if="member.userId !== project.ownerUserId" icon="mdi-close" variant="text" :aria-label="`Gỡ ${member.user.fullName} khỏi dự án`" @click="askRemove(member)" /></template></v-list-item><v-divider v-if="index < members.length - 1" /></template><v-list-item v-if="!members.length" title="Chưa có thành viên" /></v-list></v-card></section></v-window-item>
        <v-window-item value="activity"><section aria-labelledby="activity-heading"><h2 id="activity-heading" class="text-h6 mb-3">Hoạt động gần đây</h2><v-card variant="outlined"><v-timeline density="compact" side="end" class="pa-4"><v-timeline-item v-for="item in activity" :key="item.id" dot-color="primary" size="small"><div class="font-weight-medium">{{ activityLabel(item.action) }}</div><div class="text-caption text-medium-emphasis">{{ item.user?.fullName ?? 'Hệ thống' }} · {{ localDateTime(item.createdAt) }}</div></v-timeline-item><p v-if="!activity.length" class="text-medium-emphasis">Chưa có hoạt động để hiển thị.</p></v-timeline></v-card></section></v-window-item>
      </v-window>
    </template>

    <v-dialog v-model="projectDialog" max-width="680"><v-card><v-card-title>Chỉnh sửa dự án</v-card-title><v-card-text><v-alert v-if="dialogError" type="error" density="compact" class="mb-3">{{ dialogError }}</v-alert><v-form ref="projectFormRef" @submit.prevent="saveProjectForm"><v-row><v-col cols="12" sm="8"><v-text-field v-model.trim="projectForm.name" label="Tên dự án *" :rules="[required]" variant="outlined" /></v-col><v-col cols="12" sm="4"><v-select v-model="projectForm.status" label="Trạng thái" :items="projectStatuses" variant="outlined" /></v-col><v-col cols="12"><v-textarea v-model.trim="projectForm.description" label="Mô tả" rows="2" variant="outlined" /></v-col><v-col cols="12" sm="6"><v-select v-model="projectForm.clientContactId" label="Khách hàng liên kết" :items="contacts" item-title="fullName" item-value="id" clearable variant="outlined" /></v-col><v-col cols="12" sm="6"><v-select v-model="projectForm.priority" label="Mức ưu tiên" :items="priorities" variant="outlined" /></v-col><v-col cols="12" sm="6"><v-text-field v-model="projectForm.startAt" type="date" label="Ngày bắt đầu" variant="outlined" /></v-col><v-col cols="12" sm="6"><v-text-field v-model="projectForm.dueAt" type="date" label="Hạn hoàn thành" :rules="[validDates]" variant="outlined" /></v-col></v-row></v-form></v-card-text><v-card-actions><v-spacer /><v-btn variant="text" @click="projectDialog = false">Hủy</v-btn><v-btn color="primary" :loading="saving" @click="saveProjectForm">Lưu</v-btn></v-card-actions></v-card></v-dialog>
    <v-dialog v-model="taskDialog" max-width="620"><v-card><v-card-title>Thêm công việc</v-card-title><v-card-text><v-alert v-if="dialogError" type="error" density="compact" class="mb-3">{{ dialogError }}</v-alert><v-form ref="taskFormRef" @submit.prevent="saveTask"><v-text-field v-model.trim="taskForm.title" label="Tên công việc *" :rules="[required]" variant="outlined" /><v-textarea v-model.trim="taskForm.description" label="Mô tả" rows="2" variant="outlined" /><v-row><v-col cols="6"><v-select v-model="taskForm.status" label="Trạng thái" :items="taskStatuses" variant="outlined" /></v-col><v-col cols="6"><v-select v-model="taskForm.priority" label="Ưu tiên" :items="priorities" variant="outlined" /></v-col><v-col cols="12" sm="6"><v-select v-model="taskForm.assigneeUserId" label="Người được giao" :items="memberUsers" item-title="fullName" item-value="id" clearable variant="outlined" /></v-col><v-col cols="12" sm="6"><v-select v-model="taskForm.milestoneId" label="Thuộc mốc" :items="milestones" item-title="title" item-value="id" clearable variant="outlined" /></v-col><v-col cols="12"><v-text-field v-model="taskForm.dueAt" label="Hạn hoàn thành" type="date" variant="outlined" /></v-col></v-row></v-form></v-card-text><v-card-actions><v-spacer /><v-btn variant="text" @click="taskDialog = false">Hủy</v-btn><v-btn color="primary" :loading="saving" @click="saveTask">Thêm</v-btn></v-card-actions></v-card></v-dialog>
    <v-dialog v-model="milestoneDialog" max-width="560"><v-card><v-card-title>Thêm mốc công việc</v-card-title><v-card-text><v-alert v-if="dialogError" type="error" density="compact" class="mb-3">{{ dialogError }}</v-alert><v-form ref="milestoneFormRef" @submit.prevent="saveMilestone"><v-text-field v-model.trim="milestoneForm.title" label="Tên mốc *" :rules="[required]" variant="outlined" /><v-textarea v-model.trim="milestoneForm.description" label="Mô tả / bằng chứng hoàn thành" rows="2" variant="outlined" /><v-row><v-col cols="6"><v-text-field v-model="milestoneForm.dueAt" label="Hạn hoàn thành" type="date" variant="outlined" /></v-col><v-col cols="6"><v-select v-model="milestoneForm.status" label="Trạng thái" :items="milestoneStatuses" variant="outlined" /></v-col></v-row></v-form></v-card-text><v-card-actions><v-spacer /><v-btn variant="text" @click="milestoneDialog = false">Hủy</v-btn><v-btn color="primary" :loading="saving" @click="saveMilestone">Thêm</v-btn></v-card-actions></v-card></v-dialog>
    <v-dialog v-model="memberDialog" max-width="480"><v-card><v-card-title>Thêm thành viên</v-card-title><v-card-text><v-alert v-if="dialogError" type="error" density="compact" class="mb-3">{{ dialogError }}</v-alert><v-select v-model="memberForm.userId" label="Người dùng *" :items="availableUsers" item-title="fullName" item-value="id" variant="outlined" /><v-select v-model="memberForm.access" label="Vai trò trong dự án" :items="accessOptions" variant="outlined" /></v-card-text><v-card-actions><v-spacer /><v-btn variant="text" @click="memberDialog = false">Hủy</v-btn><v-btn color="primary" :loading="saving" :disabled="!memberForm.userId" @click="saveMember">Lưu</v-btn></v-card-actions></v-card></v-dialog>
    <v-dialog v-model="removeDialog" max-width="440"><v-card><v-card-title>Gỡ thành viên?</v-card-title><v-card-text>Thành viên sẽ mất quyền truy cập dự án này. Dữ liệu công việc không bị xóa.</v-card-text><v-card-actions><v-spacer /><v-btn variant="text" @click="removeDialog = false">Hủy</v-btn><v-btn color="error" :loading="saving" @click="removeSelected">Gỡ thành viên</v-btn></v-card-actions></v-card></v-dialog>
    <v-snackbar v-model="success" color="success" timeout="3000">Đã lưu thay đổi.</v-snackbar>
  </main>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue';
import { useRoute } from 'vue-router';
import { PRIORITY_OPTIONS, PROJECT_STATUS_OPTIONS, TASK_STATUS_OPTIONS, dateInput, isOverdue, localDate, priorityColor, priorityLabel, statusColor, statusLabel, type ProjectMember, type ProjectMilestone, type ProjectTask, useProjectDetail, useProjectResources } from '@/composables/use-projects';

const route = useRoute(); const projectId = String(route.params.id); const tab = ref('overview'); const saving = ref(false); const success = ref(false); const dialogError = ref('');
const projectDialog = ref(false); const taskDialog = ref(false); const milestoneDialog = ref(false); const memberDialog = ref(false); const removeDialog = ref(false); const selectedMember = ref<ProjectMember | null>(null);
const projectFormRef = ref(); const taskFormRef = ref(); const milestoneFormRef = ref();
const { contacts, users, load: loadResources } = useProjectResources(); const { project, tasks, milestones, members, activity, loading, error, load, saveProject, addTask, updateTask, addMilestone, updateMilestone, saveMember: saveMemberRequest, removeMember } = useProjectDetail(projectId);
const projectStatuses = PROJECT_STATUS_OPTIONS; const taskStatuses = TASK_STATUS_OPTIONS; const priorities = PRIORITY_OPTIONS; const milestoneStatuses = [{ title: 'Chờ thực hiện', value: 'pending' }, { title: 'Đang thực hiện', value: 'in_progress' }, { title: 'Hoàn thành', value: 'completed' }]; const accessOptions = [{ title: 'Quản lý dự án', value: 'manager' }, { title: 'Thành viên', value: 'member' }, { title: 'Chỉ xem', value: 'viewer' }];
const projectForm = reactive({ name: '', description: '', clientContactId: '', status: 'planned', priority: 'normal', startAt: '', dueAt: '' }); const taskForm = reactive({ title: '', description: '', status: 'todo', priority: 'normal', assigneeUserId: '', milestoneId: '', dueAt: '' }); const milestoneForm = reactive({ title: '', description: '', dueAt: '', status: 'pending' }); const memberForm = reactive({ userId: '', access: 'member' });
const tasksByStatus = computed(() => Object.fromEntries(taskStatuses.map(status => [status.value, tasks.value.filter(task => task.status === status.value)])) as Record<string, ProjectTask[]>); const memberUsers = computed(() => members.value.map(member => member.user)); const availableUsers = computed(() => users.value.filter(user => !members.value.some(member => member.userId === user.id)));
const required = (value: string) => Boolean(value?.trim()) || 'Trường này là bắt buộc'; const validDates = () => !projectForm.startAt || !projectForm.dueAt || projectForm.dueAt >= projectForm.startAt || 'Hạn hoàn thành phải sau ngày bắt đầu';
const apiError = (cause: unknown, fallback: string) => (cause as { response?: { data?: { error?: string } } }).response?.data?.error ?? fallback;
const money = (value: number) => new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND', maximumFractionDigits: 0 }).format(value);
const localDateTime = (value: string) => new Intl.DateTimeFormat('vi-VN', { dateStyle: 'medium', timeStyle: 'short', timeZone: 'Asia/Ho_Chi_Minh' }).format(new Date(value));
function accessLabel(value: string) { return ({ manager: 'Quản lý', member: 'Thành viên', viewer: 'Chỉ xem' } as Record<string, string>)[value] ?? value; } function activityLabel(value: string) { return ({ 'project.created': 'Đã tạo dự án', 'project.updated': 'Đã cập nhật dự án', 'project.task_created': 'Đã tạo công việc', 'project.task_updated': 'Đã cập nhật công việc', 'project.milestone_created': 'Đã tạo mốc', 'project.milestone_updated': 'Đã cập nhật mốc', 'project.member_saved': 'Đã cập nhật thành viên', 'project.member_removed': 'Đã gỡ thành viên' } as Record<string, string>)[value] ?? value; }
function openProjectEdit() { if (!project.value) return; Object.assign(projectForm, { name: project.value.name, description: project.value.description ?? '', clientContactId: project.value.clientContactId ?? '', status: project.value.status, priority: project.value.priority, startAt: dateInput(project.value.startAt), dueAt: dateInput(project.value.dueAt) }); dialogError.value = ''; projectDialog.value = true; }
function openTask() { Object.assign(taskForm, { title: '', description: '', status: 'todo', priority: 'normal', assigneeUserId: '', milestoneId: '', dueAt: '' }); dialogError.value = ''; taskDialog.value = true; } function openMilestone() { Object.assign(milestoneForm, { title: '', description: '', dueAt: '', status: 'pending' }); dialogError.value = ''; milestoneDialog.value = true; } function openMember() { Object.assign(memberForm, { userId: '', access: 'member' }); dialogError.value = ''; memberDialog.value = true; }
async function run(action: () => Promise<void>, done: () => void) { saving.value = true; dialogError.value = ''; try { await action(); done(); success.value = true; } catch (cause) { dialogError.value = apiError(cause, 'Không thể lưu thay đổi.'); } finally { saving.value = false; } }
async function saveProjectForm() { const result = await projectFormRef.value?.validate(); if (result && !result.valid) return; await run(async () => saveProject({ ...projectForm, clientContactId: projectForm.clientContactId || null, startAt: projectForm.startAt || null, dueAt: projectForm.dueAt || null }), () => { projectDialog.value = false; }); }
async function saveTask() { const result = await taskFormRef.value?.validate(); if (result && !result.valid) return; await run(async () => addTask({ ...taskForm, assigneeUserId: taskForm.assigneeUserId || null, milestoneId: taskForm.milestoneId || null, dueAt: taskForm.dueAt || null }), () => { taskDialog.value = false; }); }
async function moveTask(task: ProjectTask, status: string) { if (status === task.status) return; await run(async () => updateTask(task.id, { status }), () => undefined); }
async function saveMilestone() { const result = await milestoneFormRef.value?.validate(); if (result && !result.valid) return; await run(async () => addMilestone({ ...milestoneForm, dueAt: milestoneForm.dueAt || null }), () => { milestoneDialog.value = false; }); }
async function changeMilestone(milestone: ProjectMilestone, status: string) { if (status === milestone.status) return; await run(async () => updateMilestone(milestone.id, { status }), () => undefined); }
async function saveMember() { await run(async () => saveMemberRequest(memberForm), () => { memberDialog.value = false; }); } function askRemove(member: ProjectMember) { selectedMember.value = member; removeDialog.value = true; }
async function removeSelected() { if (!selectedMember.value) return; await run(async () => removeMember(selectedMember.value!.userId), () => { removeDialog.value = false; selectedMember.value = null; }); }
onMounted(async () => { await Promise.all([load(), loadResources()]); });
</script>

<style scoped>
.summary-grid { display: grid; grid-template-columns: minmax(130px, .8fr) 1.2fr; gap: 16px; margin: 0; } .summary-grid dt { color: rgb(var(--v-theme-on-surface-variant)); } .summary-grid dd { margin: 0; }
.task-board { display: grid; grid-template-columns: repeat(5, minmax(220px, 1fr)); gap: 16px; overflow-x: auto; padding-bottom: 8px; } .task-column { min-height: 280px; padding: 12px; border-radius: 8px; background: rgb(var(--v-theme-surface-variant)); } .milestone-status { width: 178px; }
@media (max-width: 599px) { .milestone-status { width: 130px; } }
</style>
